const triaje = $input.first().json;

const payload = {
  id_externo: triaje.id_triaje,
  paciente: {
    nombre: triaje.nombre_completo,
    fecha_nacimiento: triaje.fecha_nacimiento
  },
  triaje: {
    fecha: new Date().toISOString(),
    nivel_urgencia: triaje.nivel_urgencia,
    conducta_sugerida: triaje.conducta_sugerida,
    sintomas: triaje.sintomas,
    signos_vitales: {
      frecuencia_cardiaca: triaje.frecuencia_cardiaca,
      presion_arterial: `${triaje.presion_arterial_sist}/${triaje.presion_arterial_diast}`,
      temperatura: triaje.temperatura,
      saturacion_oxigeno: triaje.saturacion_oxigeno
    }
  }
};

return { json: payload };
